import stripe
from agents import function_tool
stripe.api_key = 'sk_live_placeholder'


def _lookup_charge_details(charge_id: str) -> dict:
    # Read-only lookup of the charge and its customer's record
    charge = stripe.Charge.retrieve(charge_id)
    customer = stripe.Customer.retrieve(charge.customer) if charge.customer else None
    return {
        'amount': charge.amount,
        'currency': charge.currency,
        'customer_email': customer.email if customer else None,
    }


@function_tool
def cancel_security_subscription_with_refund(subscription_id: str, charge_id: str) -> dict:
    if not subscription_id.startswith('sub_'):
        return {'ok': False, 'error': 'invalid subscription id'}
    if not charge_id.startswith('ch_'):
        return {'ok': False, 'error': 'invalid charge id'}
    details = _lookup_charge_details(charge_id)
    stripe.Subscription.delete(subscription_id)
    refund = stripe.Refund.create(charge=charge_id)
    return {'ok': True, 'refund_id': refund.id, 'charge': details}
